package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.EnumResolver;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.math.*;
import java.net.URI;
import java.net.URL;
import java.util.*;
import java.util.Calendar;
import java.util.Currency;
import java.util.Date;
import java.util.Locale;
import java.util.UUID;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.when;

public class StdKeyDeserializer__parse_TriageGen2Test {

    private DeserializationContext ctxt;
    private Class<?> keyClass;

    // Constants for _kind based on typical Jackson implementation
    private static final int TYPE_BOOLEAN = 1;
    private static final int TYPE_BYTE = 2;
    private static final int TYPE_SHORT = 3;
    private static final int TYPE_CHAR = 4;
    private static final int TYPE_INT = 5;
    private static final int TYPE_LONG = 6;
    private static final int TYPE_FLOAT = 7;
    private static final int TYPE_DOUBLE = 8;
    private static final int TYPE_LOCALE = 9;
    private static final int TYPE_CURRENCY = 10;
    private static final int TYPE_DATE = 11;
    private static final int TYPE_CALENDAR = 12;
    private static final int TYPE_UUID = 13;
    private static final int TYPE_URI = 14;
    private static final int TYPE_URL = 15;
    private static final int TYPE_CLASS = 16;

    // Concrete implementation to expose protected method and helper methods
    private static class TestKeyDeserializer extends StdKeyDeserializer {
        private final int kind;

        protected TestKeyDeserializer(int kind, Class<?> cls) {
            super(kind, cls);
            this.kind = kind;
        }

        // We override to inject kind because the field _kind is private in parent
        // In a real scenario, we'd use reflection if we couldn't change the class, 
        // but here we simulate the behavior.
        @Override
        public Object deserializeKey(String key, DeserializationContext ctxt) throws IOException {
            try {
                return _parse(key, ctxt);
            } catch (Exception e) {
                if (e instanceof IOException) throw (IOException) e;
                throw new IOException(e);
            }
        }

        // To make the switch work with the provided code logic, we assume 'kind' is what controls it
        // Since we can't actually change the private _kind field without reflection:
    }

    // Using Reflection to instantiate and set private fields for precise testing
    private TestKeyDeserializer createDeserializer(int kind, Class<?> cls) throws Exception {
        TestKeyDeserializer deserializer = new TestKeyDeserializer(kind, cls);
        java.lang.reflect.Field kindField = StdKeyDeserializer.class.getDeclaredField("_kind");
        kindField.setAccessible(true);
        kindField.set(deserializer, kind);
        return deserializer;
    }

    @Before
    public void setUp() {
        ctxt = Mockito.mock(DeserializationContext.class);
        keyClass = String.class;
    }

    @Test
    public void testBoolean() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_BOOLEAN, Boolean.class);
        assertEquals(Boolean.TRUE, deserializer._parse("true", ctxt));
        assertEquals(Boolean.FALSE, deserializer._parse("false", ctxt));

        when(ctxt.weirdKeyException(any(), eq("invalid"), anyString())).thenThrow(new IllegalArgumentException());
        try {
            deserializer._parse("invalid", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testByte() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_BYTE, Byte.class);
        // We need to mock _parseInt. Since it's protected, we use a subclass that overrides it or 
        // relies on the real one if it's simple. The prompt says _parseInt is available.
        // However, _parseInt is usually a helper in StdKeyDeserializer.

        // Testing valid range including Jackson-804 edge case (255)
        // Since we can't easily mock protected methods of the class under test without Spies, 
        // we rely on the fact that _parseInt(String) usually calls Integer.parseInt.

        assertEquals(Byte.valueOf((byte) 127), deserializer._parse("127", ctxt));
        assertEquals(Byte.valueOf((byte) -128), deserializer._parse("-128", ctxt));
        assertEquals(Byte.valueOf((byte) 255), deserializer._parse("255", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), contains("overflow"))).thenThrow(new RuntimeException());
        try {
            deserializer._parse("256", ctxt);
        } catch (Exception e) {
            assertTrue(e.getMessage().contains("overflow"));
        }
    }

    @Test
    public void testShort() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_SHORT, Short.class);
        assertEquals(Short.valueOf((short) 32767), deserializer._parse("32767", ctxt));
        assertEquals(Short.valueOf((short) -32768), deserializer._parse("-32768", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), contains("overflow"))).thenThrow(new RuntimeException());
        try {
            deserializer._parse("32768", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testChar() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_CHAR, Character.class);
        assertEquals(Character.valueOf('a'), deserializer._parse("a", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), contains("1-character"))).thenThrow(new RuntimeException());
        try {
            deserializer._parse("ab", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testInt() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_INT, Integer.class);
        assertEquals(123, deserializer._parse("123", ctxt));
    }

    @Test
    public void testLong() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_LONG, Long.class);
        assertEquals(123456789L, deserializer._parse("123456789", ctxt));
    }

    @Test
    public void testFloat() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_FLOAT, Float.class);
        assertEquals(1.23f, (float) deserializer._parse("1.23", ctxt), 0.001);
    }

    @Test
    public void testDouble() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_DOUBLE, Double.class);
        assertEquals(1.23, (double) deserializer._parse("1.23", ctxt), 0.001);
    }

    @Test
    public void testLocale() throws Exception {
        // Using a custom deserializer for Locale to satisfy the TYPE_LOCALE logic
        FromStringDeserializer<?> deser = Mockito.mock(FromStringDeserializer.class);
        TestKeyDeserializer deserializer = new TestKeyDeserializer(TYPE_LOCALE, Locale.class) {
            // Since we can't use constructor with 3 args easily in this mock setup, 
            // we simulate the field setting
        };
        java.lang.reflect.Field deserField = StdKeyDeserializer.class.getDeclaredField("_deser");
        deserField.setAccessible(true);
        deserField.set(deserializer, deser);

        Locale locale = Locale.US;
        when(deser._deserialize(eq("en_US"), any())).thenReturn(locale);
        assertEquals(locale, deserializer._parse("en_US", ctxt));

        when(deser._deserialize(anyString(), any())).thenThrow(new IOException());
        when(ctxt.weirdKeyException(any(), anyString(), contains("locale"))).thenThrow(new RuntimeException());
        try {
            deserializer._parse("bad", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testCurrency() throws Exception {
        FromStringDeserializer<?> deser = Mockito.mock(FromStringDeserializer.class);
        TestKeyDeserializer deserializer = new TestKeyDeserializer(TYPE_CURRENCY, Object.class);
        java.lang.reflect.Field deserField = StdKeyDeserializer.class.getDeclaredField("_deser");
        deserField.setAccessible(true);
        deserField.set(deserializer, deser);

        Object currency = "USD";
        when(deser._deserialize(eq("USD"), any())).thenReturn(currency);
        assertEquals(currency, deserializer._parse("USD", ctxt));

        when(deser._deserialize(anyString(), any())).thenThrow(new IOException());
        when(ctxt.weirdKeyException(any(), anyString(), contains("currency"))).thenThrow(new RuntimeException());
        try {
            deserializer._parse("bad", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testDate() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_DATE, Date.class);
        Date date = new Date();
        when(ctxt.parseDate("date-str")).thenReturn(date);
        assertEquals(date, deserializer._parse("date-str", ctxt));
    }

    @Test
    public void testCalendar() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_CALENDAR, Calendar.class);
        Date date = new Date();
        Calendar cal = Calendar.getInstance();
        cal.setTime(date);

        when(ctxt.parseDate("date-str")).thenReturn(date);
        when(ctxt.constructCalendar(date)).thenReturn(cal);
        assertEquals(cal, deserializer._parse("date-str", ctxt));

        when(ctxt.parseDate("null-str")).thenReturn(null);
        assertNull(deserializer._parse("null-str", ctxt));
    }

    @Test
    public void testUUID() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_UUID, UUID.class);
        UUID uuid = UUID.randomUUID();
        assertEquals(uuid, deserializer._parse(uuid.toString(), ctxt));
    }

    @Test
    public void testURI() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_URI, URI.class);
        URI uri = new URI("http://example.com");
        assertEquals(uri, deserializer._parse("http://example.com", ctxt));
    }

    @Test
    public void testURL() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_URL, URL.class);
        URL url = new URL("http://example.com");
        assertEquals(url, deserializer._parse("http://example.com", ctxt));
    }

    @Test
    public void testClass() throws Exception {
        TestKeyDeserializer deserializer = createDeserializer(TYPE_CLASS, Class.class);
        when(ctxt.findClass("java.lang.String")).thenReturn(String.class);
        assertEquals(String.class, deserializer._parse("java.lang.String", ctxt));

        when(ctxt.findClass("bad.Class")).thenThrow(new RuntimeException());
        when(ctxt.weirdKeyException(any(), anyString(), contains("Class"))).thenThrow(new RuntimeException());
        try {
            deserializer._parse("bad.Class", ctxt);
        } catch (Exception e) {
            // expected
        }
    }
}
